58		before := s.Decide(org, req)
59		wantBefore := Decision{
60			Allowed: true, Reason: "matched allow policy",
61			Matched: []string{"p-ledger-read"}, Version: 2,
62		}
63		if !reflect.DeepEqual(before, wantBefore) {
64			t.Fatalf("decision under v2 = %+v, want %+v", before, wantBefore)
65		}
