func printAuditRecord(r darksafe.AuditRecord) {
	switch r.Kind {
	case darksafe.AuditPolicyChange:
		c := r.Change
		fmt.Printf("  seq=%d %-14s version=%d source=%d rolled-back=%-5v policies=%q\n",
